const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict');
const {oracleRequire,verifyPackage}=require('../oracle-packages.cjs');verifyPackage('starknet');
const {typedData}=oracleRequire('starknet'),bases=JSON.parse(fs.readFileSync(path.join(__dirname,'typed-data.json'),'utf8')).cases;
const p=3618502788666131213697322783095070105623107215331596699973092056135872020481n,cases=[];
function capture(name,revision,kind,value,setup) {const data=JSON.parse(bases[revision].raw);data.types.Message=[{name:'x',type:kind}];data.message={x:value};if(setup)setup(data);const raw=JSON.stringify(data),row={name,revision,kind,raw,address:'0x1234'};try{row.hash=typedData.getMessageHash(JSON.parse(raw),row.address);}catch(error){row.error={name:error.name,message:error.message};}cases.push(row);}
for(const [kind,field] of [['TokenAmount','token_address'],['NftId','collection_address']])for(const [edge,value] of [['zero','0'],['one','1'],['p',p.toString()],['p-plus-one',(p+1n).toString()],['hex-p','0x'+p.toString(16)]]) {const payload=kind==='TokenAmount'?{token_address:value,amount:{low:1,high:0}}:{collection_address:value,token_id:{low:1,high:0}};capture(`rev1/${kind}/${edge}`,1,kind,payload);capture(`rev1/${kind}-array/${edge}`,1,kind+'*',[payload]);}
for(const revision of [0,1])for(const kind of ['selector','string','i128','u128','timestamp','bool'])for(const [edge,value] of [['one','1'],['p',p.toString()],['hex-p','0x'+p.toString(16)],['negative','-1']])capture(`rev${revision}/${kind}/${edge}`,revision,kind,value);
for(const [name,kind,value] of [['unknown-number','FuturePreset',p.toString()],['unknown-record','FuturePreset',{field:p.toString()}],['shadow-felt','felt',p.toString()],['shadow-preset','TokenAmount',{token_address:p.toString(),amount:{low:1,high:0}}]])capture(name,1,kind,value,name.startsWith('shadow')?data=>{data.types[kind]=[{name:'safe',type:'felt'}];}:undefined);
const target=path.join(__dirname,'typed-closed-kinds.json'),result=JSON.stringify({oracle:'pinned Stark SDK presets, every non-composite kind and unrecognized/shadowed schemas',cases},null,2)+'\n';
if(process.argv.includes('--capture'))fs.writeFileSync(target,result,{flag:'wx'});else assert.equal(result,fs.readFileSync(target,'utf8'),'Stark closed-kind oracle drift');
